pragma solidity >=0.8.0;

contract IntDivShiftBoundaryCounts {
    uint256 public count;

    function sar8(int8 x, uint8 n) public returns (int8) {
        int8 r = x >> n;
        count++;
        return r;
    }

    function shr256(uint256 x, uint256 n) public returns (uint256) {
        uint256 r = x >> n;
        count++;
        return r;
    }
}

